    function run(address probeOwner) public payable {
        require(msg.sender != probeOwner);
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        require(beforeOwner != address(this));
        bool reverted;
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.owner() == beforeOwner);
    }
    receive() external payable {}
