    function _run(address probeOwner) internal {
        vm.assume(msg.sender != probeOwner);
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        vm.assume(beforeOwner != address(this));
        bool reverted;
